// A compact, non-cryptographic fingerprint (djb2) for "did the rendered quote content change"
// checks — deliberately NOT embedding the raw content itself, which is what previously bloated
// the project document with a full copy of every quote page's HTML on every save.
function hashQuoteSnapshotContent(input: string): string {
  let hash = 5381;
  for (let i = 0; i < input.length; i += 1) {
    hash = ((hash << 5) + hash + input.charCodeAt(i)) | 0;
  }
  return (hash >>> 0).toString(36);
}
