type ProjectStatusRow = { name: string; color: string };
const statusDefaults = ["New", "Quoting", "Drafting", "Ready for CNC", "Running", "In Production", "Paused", "Completed"];
function fallbackStatusPillColors(status: string) {
  const key = String(status || "").trim().toLowerCase();
  const defaults: Record<string, string> = {
    new: "#3060D0",
    running: "#2A7A3B",
    "in production": "#2A7A3B",
    drafting: "#6B4FB3",
    quoting: "#C77700",
    "ready for cnc": "#3060D0",
    completed: "#2A7A3B",
    paused: "#A05A00",
    complete: "#2A7A3B",
    "on hold": "#C77700",
  };
  const bg = defaults[key] ?? "#64748B";
  return { backgroundColor: bg, color: "#FFFFFF" };
}

function normalizeProjectStatuses(raw: unknown): ProjectStatusRow[] {
  if (!Array.isArray(raw)) {
    return [
      { name: "New", color: "#3060D0" },
      { name: "In Production", color: "#2A7A3B" },
      { name: "On Hold", color: "#C77700" },
      { name: "Complete", color: "#2A7A3B" },
    ];
  }
  const rows = raw
    .filter((item) => item && typeof item === "object")
    .map((item) => {
      const row = item as Record<string, unknown>;
      return {
        name: String(row.name ?? "").trim(),
        color: String(row.color ?? "").trim() || "#64748B",
      };
    })
    .filter((row) => row.name);
  return rows.length
    ? rows
    : [
        { name: "New", color: "#3060D0" },
        { name: "In Production", color: "#2A7A3B" },
        { name: "On Hold", color: "#C77700" },
        { name: "Complete", color: "#2A7A3B" },
      ];
}

function shortDate(value: string) {
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) {
    return "-";
  }
  return d.toLocaleString();
}

function dashboardStyleDate(value: string) {
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) {
    return "-";
  }
  const date = new Intl.DateTimeFormat("en-NZ", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  }).format(d);
  const time = new Intl.DateTimeFormat("en-NZ", {
    hour: "numeric",
    minute: "2-digit",
    hour12: true,
  })
    .format(d)
    .toLowerCase()
    .replace(" ", "");
  return `${date} | ${time}`;
}

// Same shape as dashboardStyleDate, just with the short month style (en-NZ's own convention —
// e.g. "Sept" for September, plain 3-letter for the rest) instead of the full name — used for the
// Specifications "Version History" bubble cards specifically, which are narrow enough that the
// full month name crowds the rest of the line.
function shortMonthStyleDate(value: string) {
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) {
    return "-";
  }
  const date = new Intl.DateTimeFormat("en-NZ", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  }).format(d);
  const time = new Intl.DateTimeFormat("en-NZ", {
    hour: "numeric",
    minute: "2-digit",
    hour12: true,
  })
    .format(d)
    .toLowerCase()
    .replace(" ", "");
  return `${date} | ${time}`;
}

// DD/MM/YYYY (never MM/DD, regardless of the viewer's own browser locale) plus a separate 12-hour
// time string — used by the Quote "Pending"/"Accepted" banners above the sheet, where the exact
// date the client acted matters and shouldn't silently flip ordering for a US-locale browser.
function numericDDMMYYYYAndTime(value: string): { date: string; time: string } {
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return { date: "-", time: "-" };
  const date = new Intl.DateTimeFormat("en-GB", { day: "2-digit", month: "2-digit", year: "numeric" }).format(d);
  const time = new Intl.DateTimeFormat("en-NZ", { hour: "numeric", minute: "2-digit", hour12: true })
    .format(d)
    .toLowerCase()
    .replace(" ", "");
  return { date, time };
}

// "1st"/"2nd"/"3rd"/"4th"..."11th"/"12th"/"13th" (the 11-13 teens are always "th", not "st"/"nd"/
// "rd", despite ending in 1/2/3) — standard English ordinal rule.
function ordinalSuffix(day: number): string {
  if (day % 100 >= 11 && day % 100 <= 13) return "th";
  switch (day % 10) {
    case 1:
      return "st";
    case 2:
      return "nd";
    case 3:
      return "rd";
    default:
      return "th";
  }
}

function dashboardStyleDateOnly(value: string) {
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) {
    return "-";
  }
  const day = d.getDate();
  const monthYear = new Intl.DateTimeFormat("en-NZ", {
    month: "long",
    year: "numeric",
  }).format(d);
  return `${day}${ordinalSuffix(day)} ${monthYear}`;
}

function initials(text: string) {
  const cleaned = String(text || "").trim();
  if (!cleaned) return "?";
  const parts = cleaned.split(/\s+/).filter(Boolean);
  if (parts.length === 1) {
    return parts[0].slice(0, 2).toUpperCase();
  }
  return `${parts[0][0] ?? ""}${parts[1][0] ?? ""}`.toUpperCase();
}


function quoteColumnWidthPercent(span: number): number {
  const safeSpan = Math.max(1, Math.min(12, Number(span) || 12));
  return (safeSpan / 12) * 100;
}

function quotePaperDimensionsFor(pageSize: string): { widthMm: number; heightMm: number } {
  const key = String(pageSize || "").trim().toUpperCase();
  switch (key) {
    case "A3":
      return { widthMm: 297, heightMm: 420 };
    case "A5":
      return { widthMm: 148, heightMm: 210 };
    case "LETTER":
      return { widthMm: 216, heightMm: 279 };
    case "LEGAL":
      return { widthMm: 216, heightMm: 356 };
    case "A4":
    default:
      return { widthMm: 210, heightMm: 297 };
  }
}

