  createdAt: string;
  createdByUid: string;
  createdByName: string;
  // Only meaningful on the "last closed" row: the project's own updatedAtIso marker at the
  // moment this snapshot was captured. Persisted (unlike an in-memory ref) so the "is the quote
  // outdated relative to the project" check survives a full page reload.
