    const explicitAssignedName =
      toStr(projectAssignedMember?.displayName, "") ||
      toStr(project?.assignedToName, "") ||
      toStr(project?.assignedTo, "");
    const explicitAssignedKey = normalizePersonLookup(explicitAssignedName);
    const creatorKey = normalizePersonLookup(creatorDisplayName);
