    // in-memory ref — an in-memory baseline resets to "current" on every full page reload (a
    // fresh page load re-reads the project fresh, so there's nothing stale to compare against),
    // which is exactly when a user is most likely to be opening Quote after changing something
    // elsewhere. Comparing against the persisted marker instead makes this reload-proof.
    const baseline = quoteLastClosedSnapshot?.capturedProjectMarker || "";
    if (!baseline) return;
    let cancelled = false;
    (async () => {
      const fresh = await fetchProjectUpdatedAtMarker(activeProject);
      if (cancelled) return;
      if (fresh && fresh > baseline) {
        setIsQuoteOutdated(true);
        openQuoteSnapshotVersion("quote_last_closed");
      }
    })();
    return () => {
      cancelled = true;
    };
    // quoteLastClosedSnapshot is included so this also re-checks if the "last closed" capture
