    if (trimmedValue.trim()) nextQuoteProjectText[blockId] = trimmedValue;
    else delete nextQuoteProjectText[blockId];
    const nextSales = {
      ...salesPayload,
      quoteProjectText: nextQuoteProjectText,
    } as Record<string, unknown>;
    setIsSavingQuoteProjectText(true);
