                                      const editingThisInfoCell = col.key === "information" && isEditing(row.id, "information");
                                      const pieceGrainValue = String(piece.grainValue || row.grainValue || "");
                                      let value = "";
                                      if (col.key === "partType") value = "";
                                      if (col.key === "board") value = "";
